#include "KS/SRC/ks/wave_perturb_shared.h"

enum WaveStageEnum { WAVE_StageBuilding, WAVE_StageStable, WAVE_StageSubsiding, WAVE_StageMax };
extern WaveStageEnum WAVE_Stage;
extern float WAVE_StageProgress, WAVE_StageStart[WAVE_StageMax], WAVE_StageDuration[WAVE_StageMax];
extern float WAVE_ScheduleProgress, WAVE_ScheduleTimeStart, WAVE_ScheduleTimeEnd;
extern WavePerturbStageEnum WAVE_PerturbStage;
extern float WAVE_PerturbProgress;
extern WaveBasePerturbClass *WAVE_Perturb, *WAVE_PerturbArray[WAVE_PerturbTypeMax];
extern WavePerturbTypeEnum WAVE_DebugPerturbType;
void WAVE_PerturbInit(); void WAVE_EndWave(bool); void WAVE_ScheduleAdvance();
void WAVE_StageAdvance(); void WAVE_PerturbAdvance(); void WAVE_PerturbReset(float);

__asm__(".equ WAVE_Stage,0x00585AD0\n.equ WAVE_StageProgress,0x00585AD8\n.equ WAVE_StageStart,0x004847E0\n.equ WAVE_StageDuration,0x004847D0\n.equ WAVE_ScheduleProgress,0x004846D8\n.equ WAVE_ScheduleTimeStart,0x004846DC\n.equ WAVE_ScheduleTimeEnd,0x004846E0\n.equ WAVE_PerturbStage,0x00585C44\n.equ WAVE_PerturbProgress,0x00585C6C\n.equ WAVE_Perturb,0x0057DBD8\n.equ WAVE_PerturbArray,0x00484B58\n.equ WAVE_DebugPerturbType,0x00484944\n.equ WAVE_PerturbInit__Fv,0x00376B78\n.equ WAVE_EndWave__Fb,0x00377B38\n.equ WAVE_ScheduleAdvance__Fv,0x00377920\n.equ WAVE_StageAdvance__Fv,0x00377B00\n.equ WAVE_PerturbAdvance__Fv,0x00377220\n.equ WAVE_PerturbReset__Ff,0x00377370");

void WAVE_ComputeStage(void)
{
	if (WaveDebug.BreakReload)
	{
		WAVE_PerturbInit();
	}
	if (WaveDebug.BreakFreeze)
	{
		return;
	}
	if (WaveDebug.RestartWave)
	{
		WAVE_EndWave(false);
		WaveDebug.RestartWave = false;
	}
	if (WaveDebug.EndWave)
	{
		WAVE_Stage = WAVE_StageStable;
		WAVE_PerturbStage = WAVE_PerturbStageNone;
		WAVE_PerturbProgress = 0;
		WaveDebug.EndWave = false;
	}
	WAVE_ScheduleProgress = (WAVE_GetTotalSec() - WAVE_ScheduleTimeStart)
		/ (WAVE_ScheduleTimeEnd - WAVE_ScheduleTimeStart);
	if (WAVE_ScheduleProgress >= 1.f)
		WAVE_ScheduleAdvance();
	WAVE_StageProgress = (WAVE_GetTotalSec() - WAVE_StageStart[WAVE_Stage])
		/ WAVE_StageDuration[WAVE_Stage];
	if (WAVE_StageProgress >= 1.f)
		WAVE_StageAdvance();
	float wppdwps=WAVE_Perturb->duration[WAVE_PerturbStage];
	if ( wppdwps==0.0f )
		WAVE_PerturbProgress = 1.0f;
	else
		WAVE_PerturbProgress = (WAVE_GetTotalSec() - WAVE_Perturb->start[WAVE_PerturbStage])
			/ wppdwps;
	if (WAVE_PerturbProgress >= 1.f)
		WAVE_PerturbAdvance();
	if (WaveDebug.BreakLoop &&
		(WAVE_Perturb->duration[WAVE_PerturbStageNone] > 1 || WAVE_DebugPerturbType != WAVE_PerturbType))
	{
		WAVE_PerturbType = WAVE_DebugPerturbType;
		WAVE_Perturb = WAVE_PerturbArray[WAVE_PerturbType];
		WAVE_PerturbReset(1);
	}
}
